import { useTheme } from "@/contexts/ThemeContext";
import {
  ArrowUpRight, Bell, Bookmark, Check, CheckCheck, ChevronDown, ChevronLeft, CircleHelp, Copy, File as FileIcon, Flag, Globe2,
  Hash, Headphones, Image as ImageIcon, Inbox, LayoutGrid, LockKeyhole, LogOut, Menu, MessageCircle, Mic, Moon,
  MoreHorizontal, Paperclip, PenSquare, PhoneCall, Plus, Search, Send, Settings, ShieldCheck, Smile, Sparkles, Star,
  Sun, Trash2, Upload, UserRoundPlus, UserX, Users, X, Zap
} from "lucide-react";
