type View = "chats" | "icebox" | "stories" | "contacts" | "notifications" | "settings" | "admin";

function Avatar({ name, image, size = "md", online = false }: { name?: string | null; image?: string | null; size?: "sm" | "md" | "lg"; online?: boolean }) {
  const initials = (name || "I").split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase();
  const classes = size === "lg" ? "h-14 w-14 text-lg" : size === "sm" ? "h-9 w-9 text-[11px]" : "h-11 w-11 text-sm";
  return <div className="relative shrink-0"><div className={`${classes} overflow-hidden rounded-2xl bg-gradient-to-br from-sky-200 via-cyan-200 to-blue-500 font-bold text-[#0b2858] grid place-items-center shadow-sm`}>{image ? <img src={image} alt="" className="h-full w-full object-cover" /> : initials}</div>{online && <span className="absolute -bottom-0.5 -right-0.5 h-3 w-3 rounded-full border-2 border-card bg-emerald-400" />}</div>;
}

function formatTime(value: Date | string | null | undefined) {
  if (!value) return "";
  return new Date(value).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function Landing({ onLogin }: { onLogin: () => void }) {
  return <div className="min-h-screen overflow-hidden bg-[#f6fbff] text-[#0f1d38]">
    <header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 lg:px-10">
      <IcegramLogo />
      <div className="hidden items-center gap-8 text-sm font-semibold text-[#60708c] md:flex"><a href="#why">Why Icegram</a><a href="#privacy">Privacy</a><a href="#future">Built to scale</a></div>
      <button onClick={onLogin} className="rounded-full bg-[#11294d] px-5 py-2.5 text-sm font-semibold text-white shadow-lg shadow-[#11294d]/15 transition hover:-translate-y-0.5">Sign in <ArrowUpRight className="ml-1 inline h-4 w-4" /></button>
    </header>
    <main>
      <section className="relative mx-auto grid max-w-7xl items-center gap-12 px-5 pb-24 pt-14 lg:grid-cols-[1.05fr_.95fr] lg:px-10 lg:pb-32 lg:pt-24">
        <div className="relative z-10">
          <div className="mb-6 inline-flex items-center gap-2 rounded-full border border-cyan-200 bg-white/80 px-3 py-1.5 text-xs font-bold uppercase tracking-[0.18em] text-[#2286ba]"><span className="h-2 w-2 rounded-full bg-cyan-400" /> A calmer way to connect</div>
          <h1 className="max-w-3xl text-5xl font-black leading-[.98] tracking-[-.06em] text-[#102243] sm:text-6xl lg:text-8xl">Your people,<br /><span className="bg-gradient-to-r from-[#26b8d6] via-[#4f9df3] to-[#5669e8] bg-clip-text text-transparent">one clear space.</span></h1>
          <p className="mt-7 max-w-xl text-lg leading-8 text-[#64738f]">Private conversations, expressive communities, and the tools to create together — all built around an identity you control.</p>
          <div className="mt-9 flex flex-col gap-3 sm:flex-row"><button onClick={onLogin} className="rounded-2xl bg-[#122b52] px-6 py-4 text-sm font-bold text-white shadow-xl shadow-[#102243]/20 transition hover:-translate-y-1">Create your Icegram ID <ArrowUpRight className="ml-2 inline h-4 w-4" /></button><a href="#why" className="rounded-2xl border border-[#c8d9eb] bg-white px-6 py-4 text-center text-sm font-bold text-[#233b60] transition hover:border-[#80cde4]">Explore the product</a></div>
          <div className="mt-10 flex items-center gap-5 text-xs font-semibold text-[#7a89a3]"><div className="flex -space-x-2"><Avatar name="A" size="sm" /><Avatar name="M" size="sm" /><Avatar name="J" size="sm" /></div><span>Built for real conversations<br /><b className="text-[#233b60]">with privacy by default</b></span></div>
        </div>
        <div className="relative mx-auto w-full max-w-[530px]">
          <div className="absolute -left-12 -top-10 h-64 w-64 rounded-full bg-cyan-300/30 blur-3xl" /><div className="absolute -bottom-16 -right-8 h-80 w-80 rounded-full bg-blue-300/30 blur-3xl" />
          <div className="relative rotate-2 rounded-[2.2rem] border border-white/70 bg-white/80 p-3 shadow-[0_30px_90px_rgba(35,102,164,.20)] backdrop-blur-xl"><div className="rounded-[1.8rem] bg-[#edf8ff] p-4"><div className="flex items-center justify-between border-b border-[#dbeaf4] pb-4"><div className="flex items-center gap-3"><Avatar name="Maya Chen" size="sm" online /><div><p className="text-sm font-bold text-[#17345d]">Maya Chen</p><p className="text-[11px] text-[#6e87a5]">online now</p></div></div><MoreHorizontal className="h-5 w-5 text-[#85a2bd]" /></div><div className="space-y-4 px-2 py-6"><div className="flex gap-2"><Avatar name="Maya" size="sm" /><div className="max-w-[75%] rounded-2xl rounded-tl-sm bg-white px-4 py-3 text-sm leading-5 text-[#48617e] shadow-sm">The new community space feels so much calmer already ✨</div></div><div className="ml-auto max-w-[75%] rounded-2xl rounded-tr-sm bg-[#183b70] px-4 py-3 text-sm leading-5 text-white shadow-lg shadow-[#183b70]/15">That’s the idea. More signal, less noise.<div className="mt-1 text-right text-[10px] text-white/60">10:42 <CheckCheck className="ml-1 inline h-3 w-3" /></div></div><div className="flex gap-2"><Avatar name="Maya" size="sm" /><div className="max-w-[75%] rounded-2xl rounded-tl-sm bg-white px-4 py-3 text-sm leading-5 text-[#48617e] shadow-sm">Sending the invite to our Space now.</div></div></div><div className="flex items-center gap-2 rounded-2xl bg-white px-3 py-2 shadow-sm"><Smile className="h-5 w-5 text-[#8badc5]" /><span className="flex-1 text-xs text-[#9bb0c4]">Write a message...</span><div className="grid h-8 w-8 place-items-center rounded-xl bg-[#1c9cca] text-white"><Send className="h-4 w-4" /></div></div></div></div>
          <div className="absolute -bottom-8 -left-8 rounded-2xl border border-white/80 bg-white/90 p-4 shadow-xl backdrop-blur"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e3f7fa] text-[#1e9ab4]"><LockKeyhole className="h-5 w-5" /></div><div><p className="text-xs font-black text-[#19365c]">Identity first</p><p className="mt-1 text-[10px] text-[#7c91aa]">Your number stays yours</p></div></div></div>
        </div>
      </section>
      <section id="why" className="border-y border-[#dceaf3] bg-white px-5 py-20 lg:px-10"><div className="mx-auto max-w-7xl"><div className="max-w-2xl"><p className="text-xs font-black uppercase tracking-[.22em] text-[#2ba9c4]">A foundation that grows with you</p><h2 className="mt-4 text-4xl font-black tracking-[-.04em] text-[#122849] sm:text-5xl">Everything that matters.<br />Nothing you don’t need.</h2></div><div className="mt-12 grid gap-5 md:grid-cols-3"><Feature icon={<LockKeyhole />} title="Identity without exposure" body="Your permanent Icegram ID is a private, portable way to be found — no public phone number required." /><Feature icon={<MessageCircle />} title="Conversations with context" body="Messages, groups, stories, channels, and communities stay in one purposeful, searchable home." /><Feature icon={<Zap />} title="Ready for what’s next" body="A real backend foundation for calls, AI, Spaces, creators, and developer tools as Icegram expands." /></div></div></section>
      <section id="privacy" className="mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-2 lg:px-10 lg:py-28"><div className="rounded-[2rem] bg-[#11294d] p-8 text-white shadow-2xl shadow-[#11294d]/15 sm:p-12"><ShieldCheck className="h-9 w-9 text-cyan-300" /><h2 className="mt-8 text-4xl font-black tracking-[-.04em]">Privacy is a product feature.</h2><p className="mt-5 max-w-md leading-7 text-white/65">We are explicit about what is real, what is protected, and where an external service is required. No fake encryption claims. No fake phone numbers.</p><div className="mt-8 grid gap-3 text-sm font-semibold text-white/80"><div className="flex items-center gap-3"><Check className="h-4 w-4 text-cyan-300" /> Phone number hidden by default</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-cyan-300" /> Block, report, and session controls</div><div className="flex items-center gap-3"><Check className="h-4 w-4 text-cyan-300" /> Permissioned media and file storage</div></div></div><div className="flex flex-col justify-center"><p className="text-xs font-black uppercase tracking-[.22em] text-[#2ba9c4]">Made for people, teams, and creators</p><h2 className="mt-4 text-4xl font-black tracking-[-.04em] text-[#122849]">A better place to show up.</h2><p className="mt-5 max-w-lg text-lg leading-8 text-[#6a7b95]">Use a username, Icegram ID, QR code, or contact share to connect. Keep your public identity intentional and your private life private.</p><button onClick={onLogin} className="mt-8 w-fit rounded-2xl bg-[#e6f8fc] px-5 py-3 text-sm font-bold text-[#197c9a]">Start with your identity <ArrowUpRight className="ml-1 inline h-4 w-4" /></button></div></section>
      <section id="future" className="bg-[#eaf8fc] px-5 py-20 lg:px-10"><div className="mx-auto max-w-7xl text-center"><p className="text-xs font-black uppercase tracking-[.22em] text-[#2ba9c4]">Built to scale</p><h2 className="mx-auto mt-4 max-w-2xl text-4xl font-black tracking-[-.04em] text-[#122849]">Start with a message.<br />Grow into a world.</h2><div className="mx-auto mt-10 flex max-w-4xl flex-wrap justify-center gap-3">{["Voice & video calls", "Spaces", "Icegram AI", "Bots & Mini Apps", "Business", "Creator tools", "Cloud storage", "Developer API"].map(item => <span key={item} className="rounded-full border border-[#c9eaf1] bg-white px-4 py-2 text-sm font-semibold text-[#3f6685]">{item}</span>)}</div></div></section>
    </main>
    <footer className="mx-auto flex max-w-7xl flex-col gap-4 px-5 py-8 text-xs font-semibold text-[#8292a8] sm:flex-row sm:items-center sm:justify-between lg:px-10"><IcegramLogo compact /><span>© 2026 Icegram. Connect. Chat. Create.</span></footer>
  </div>;
}

function Feature({ icon, title, body }: { icon: React.ReactNode; title: string; body: string }) { return <div className="rounded-3xl border border-[#e0edf5] bg-[#f9fcfe] p-7 transition hover:-translate-y-1 hover:shadow-lg hover:shadow-cyan-900/5"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#e6f8fc] text-[#1f9bb6]">{icon}</div><h3 className="mt-6 text-lg font-black text-[#17345d]">{title}</h3><p className="mt-3 text-sm leading-6 text-[#71849d]">{body}</p></div>; }

function Sidebar({ view, setView, profile, onLogout, notificationCount, onInstall }: { view: View; setView: (view: View) => void; profile: any; onLogout: () => void; notificationCount: number; onInstall?: () => void }) {
  const nav: { id: View; label: string; icon: React.ReactNode; badge?: number }[] = [
    { id: "chats", label: "Chats", icon: <MessageCircle /> }, { id: "icebox", label: "IceBox", icon: <Bookmark /> }, { id: "stories", label: "Stories", icon: <Star /> }, { id: "contacts", label: "Contacts", icon: <Users /> }, { id: "notifications", label: "Notifications", icon: <Bell />, badge: notificationCount }, { id: "settings", label: "Settings", icon: <Settings /> },
  ];
  return <aside className="flex w-full shrink-0 flex-col border-b border-border bg-card p-4 lg:w-[240px] lg:border-b-0 lg:border-r lg:p-5"><div className="flex items-center justify-between"><IcegramLogo compact /><div className="flex gap-2"><button onClick={() => setView("notifications")} className="relative grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted"><Bell className="h-4 w-4" />{notificationCount > 0 && <span className="absolute right-1 top-1 h-2 w-2 rounded-full bg-[#29bbd4]" />}</button><button onClick={() => setView("settings")} className="grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted"><Menu className="h-4 w-4" /></button></div></div><div className="mt-7 hidden lg:block"><p className="px-3 text-[10px] font-black uppercase tracking-[.2em] text-muted-foreground">Workspace</p><nav className="mt-3 space-y-1">{nav.map(item => <button key={item.id} onClick={() => setView(item.id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold transition ${view === item.id ? "bg-primary/10 text-primary" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}><span className="relative">{item.icon}{item.badge ? <span className="absolute -right-2 -top-2 grid min-h-4 min-w-4 place-items-center rounded-full bg-[#2dbbd2] px-1 text-[9px] font-black text-white">{item.badge > 9 ? "9+" : item.badge}</span> : null}</span>{item.label}</button>)}</nav></div><div className="mt-5 hidden border-t border-border pt-5 lg:block"><p className="px-3 text-[10px] font-black uppercase tracking-[.2em] text-muted-foreground">Coming next</p><div className="mt-3 space-y-1">{[["Calls", <PhoneCall />], ["Spaces", <LayoutGrid />], ["Icegram AI", <Sparkles />], ["Cloud", <Inbox />]].map(([label, icon]) => <div key={String(label)} className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-muted-foreground/60"><span>{icon}</span><span>{label}</span><span className="ml-auto text-[9px] font-black uppercase tracking-wider">Next</span></div>)}</div></div>{onInstall && <button onClick={onInstall} className="mt-auto hidden items-center gap-3 rounded-xl bg-[#e5f8fb] px-3 py-3 text-left text-xs font-bold text-[#187b96] lg:flex"><Upload className="h-4 w-4" /> Install PWA</button>}<div className="mt-4 flex items-center gap-3 rounded-2xl bg-muted/70 p-3"><Avatar name={profile?.displayName || profile?.name} image={profile?.avatarUrl} size="sm" online={profile?.onlineStatus !== "invisible"} /><div className="min-w-0 flex-1"><p className="truncate text-xs font-black">{profile?.displayName || profile?.name || "Your profile"}</p><p className="truncate text-[10px] text-muted-foreground">@{profile?.username || "set username"}</p></div><button onClick={onLogout} title="Sign out" className="text-muted-foreground hover:text-destructive"><LogOut className="h-4 w-4" /></button></div></aside>;
}

function MobileNav({ view, setView, count }: { view: View; setView: (v: View) => void; count: number }) { return <nav className="fixed bottom-0 left-0 right-0 z-30 flex justify-around border-t border-border bg-card/95 p-2 backdrop-blur lg:hidden">{[["chats", <MessageCircle />], ["icebox", <Bookmark />], ["stories", <Star />], ["notifications", <Bell />], ["settings", <Settings />]].map(([id, icon]) => <button key={String(id)} onClick={() => setView(id as View)} className={`relative grid h-11 w-14 place-items-center rounded-xl ${view === id ? "bg-primary/10 text-primary" : "text-muted-foreground"}`}>{icon}{id === "notifications" && count > 0 && <span className="absolute right-2 top-1 h-2 w-2 rounded-full bg-[#2dbbd2]" />}</button>)}</nav>; }

function ChatList({ chats, activeId, onSelect, onNew, onGroup, onChannel, profile }: { chats: any[]; activeId: number | null; onSelect: (id: number) => void; onNew: () => void; onGroup: () => void; onChannel: () => void; profile: any }) {
  const titleFor = (chat: any) => chat.kind === "direct" ? (chat.members.find((member: any) => member.id !== profile?.id)?.displayName || chat.members.find((member: any) => member.id !== profile?.id)?.name || "Direct chat") : chat.title || (chat.kind === "channel" ? "Channel" : "Group");
  return <section className="flex w-full shrink-0 flex-col border-b border-border bg-background md:w-[310px] md:border-b-0 md:border-r"><div className="flex items-center justify-between px-5 pb-3 pt-5"><div><p className="text-2xl font-black tracking-[-.04em]">Chats</p><p className="mt-1 text-xs text-muted-foreground">Your conversations, in one place.</p></div><button onClick={onNew} className="grid h-10 w-10 place-items-center rounded-xl bg-primary text-primary-foreground shadow-lg shadow-primary/20 transition hover:scale-105"><PenSquare className="h-4 w-4" /></button></div><div className="flex gap-2 px-5 pb-4"><button onClick={onGroup} className="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-border bg-card py-2 text-[11px] font-bold text-muted-foreground hover:border-primary/30 hover:text-primary"><Users className="h-3.5 w-3.5" /> Group</button><button onClick={onChannel} className="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-border bg-card py-2 text-[11px] font-bold text-muted-foreground hover:border-primary/30 hover:text-primary"><Hash className="h-3.5 w-3.5" /> Channel</button></div><div className="space-y-1 overflow-y-auto px-3 pb-24 md:pb-4">{chats.length === 0 ? <div className="mx-2 mt-12 rounded-2xl border border-dashed border-border p-5 text-center"><MessageCircle className="mx-auto h-7 w-7 text-muted-foreground/50" /><p className="mt-3 text-sm font-bold">No conversations yet</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Find someone by username or Icegram ID to start a real chat.</p><button onClick={onNew} className="mt-4 rounded-xl bg-primary px-3 py-2 text-xs font-bold text-primary-foreground">Start a chat</button></div> : chats.map(chat => { const title = titleFor(chat); return <button key={chat.id} onClick={() => onSelect(chat.id)} className={`flex w-full items-center gap-3 rounded-2xl p-3 text-left transition ${activeId === chat.id ? "bg-primary/10" : "hover:bg-muted"}`}><Avatar name={title} image={chat.kind === "direct" ? chat.members.find((member: any) => member.id !== profile?.id)?.avatarUrl : chat.avatarUrl} online={chat.kind === "direct"} /><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-bold">{title}</p>{chat.latest && <span className="text-[10px] text-muted-foreground">{formatTime(chat.latest.createdAt)}</span>}</div><p className="mt-1 truncate text-xs text-muted-foreground">{chat.latest?.body || (chat.latest ? `New ${chat.latest.type} message` : chat.description || (chat.kind === "channel" ? "Channel" : "No messages yet"))}</p></div></button>; })}</div></section>;
}

function ChatPane({ chat, profile, onBack }: { chat: any; profile: any; onBack: () => void }) {
  const [body, setBody] = useState("");
  const [recording, setRecording] = useState(false);
  const [busy, setBusy] = useState(false);
  const recorder = useRef<MediaRecorder | null>(null);
  const chunks = useRef<Blob[]>([]);
  const utils = trpc.useUtils();
  const input = useMemo(() => ({ conversationId: chat.id }), [chat.id]);
  const messagesQuery = trpc.chat.messages.useQuery(input, { refetchInterval: 5000 });
  const sendMutation = trpc.chat.send.useMutation({ onSuccess: () => { utils.chat.messages.invalidate(input); utils.chat.list.invalidate(); } });
  const uploadMutation = trpc.media.upload.useMutation();
  const member = chat.kind === "direct" ? chat.members.find((item: any) => item.id !== profile?.id) : null;
  const title = member?.displayName || member?.name || chat.title || "Conversation";
  const sendFile = async (file: File, type?: "image" | "file" | "voice") => {
    setBusy(true);
    try {
      const data = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1] || ""); reader.onerror = () => reject(new Error("Could not read file")); reader.readAsDataURL(file); });
      const uploaded = await uploadMutation.mutateAsync({ fileName: file.name, mimeType: file.type || "application/octet-stream", data });
      await sendMutation.mutateAsync({ conversationId: chat.id, type: type || (file.type.startsWith("image/") ? "image" : "file"), mediaUrl: uploaded.url, mediaKey: uploaded.key, fileName: uploaded.fileName, mimeType: uploaded.mimeType, fileSize: uploaded.fileSize });
      toast.success("File sent");
    } catch (error: any) { toast.error(error?.message || "Upload failed"); } finally { setBusy(false); }
  };
  const submit = async () => { if (!body.trim() || sendMutation.isPending) return; const text = body.trim(); setBody(""); try { await sendMutation.mutateAsync({ conversationId: chat.id, type: "text", body: text }); } catch (error: any) { setBody(text); toast.error(error?.message || "Message failed to send"); } };
  const startRecording = async () => {
    if (!navigator.mediaDevices?.getUserMedia || !window.MediaRecorder) { toast.error("Voice recording is not supported in this browser"); return; }
    try { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); const media = new MediaRecorder(stream); chunks.current = []; media.ondataavailable = event => { if (event.data.size) chunks.current.push(event.data); }; media.onstop = async () => { stream.getTracks().forEach(track => track.stop()); const blob = new Blob(chunks.current, { type: media.mimeType || "audio/webm" }); await sendFile(new File([blob], `voice-${Date.now()}.webm`, { type: blob.type }), "voice"); }; recorder.current = media; media.start(); setRecording(true); } catch { toast.error("Microphone access was denied"); }
  };
  const stopRecording = () => { recorder.current?.stop(); recorder.current = null; setRecording(false); };
  return <section className="flex min-h-[560px] min-w-0 flex-1 flex-col bg-[#f7fbfe] dark:bg-background"><header className="flex items-center gap-3 border-b border-border bg-card px-4 py-4 sm:px-6"><button onClick={onBack} className="grid h-9 w-9 place-items-center rounded-xl hover:bg-muted md:hidden"><ChevronLeft className="h-5 w-5" /></button><Avatar name={title} image={member?.avatarUrl} online={chat.kind === "direct"} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-black">{title}</p><p className="mt-0.5 truncate text-[11px] text-muted-foreground">{chat.kind === "direct" ? "Direct conversation · synced securely" : `${chat.kind} · ${chat.members?.length || 1} members`}</p></div><button className="grid h-9 w-9 place-items-center rounded-xl text-muted-foreground hover:bg-muted"><MoreHorizontal className="h-5 w-5" /></button></header><div className="flex-1 space-y-5 overflow-y-auto px-4 py-6 sm:px-8">{messagesQuery.isLoading ? <div className="grid h-full place-items-center text-sm text-muted-foreground">Loading messages…</div> : (messagesQuery.data ?? []).length === 0 ? <div className="grid h-full place-items-center"><div className="max-w-xs text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-primary/10 text-primary"><MessageCircle className="h-7 w-7" /></div><p className="mt-4 text-sm font-black">Start the conversation</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Send a message, image, file, or voice note. Everything here is persisted to your Icegram account.</p></div></div> : (messagesQuery.data ?? []).map(({ message, sender }: any) => { const mine = message.senderId === profile?.id; return <div key={message.id} className={`flex items-end gap-2 ${mine ? "justify-end" : "justify-start"}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 shadow-sm sm:max-w-[68%] ${mine ? "rounded-br-sm bg-[#183b70] text-white" : "rounded-bl-sm border border-border bg-card"}`}>{message.type === "image" && message.mediaUrl && <img src={message.mediaUrl} alt={message.fileName || "Shared image"} className="mb-2 max-h-64 rounded-xl object-cover" />}{message.type === "voice" && message.mediaUrl && <audio controls src={message.mediaUrl} className="mb-1 h-9 max-w-full" />}{message.type === "file" && message.mediaUrl && <a href={message.mediaUrl} target="_blank" rel="noreferrer" className={`mb-1 flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold ${mine ? "bg-white/10" : "bg-muted"}`}><FileIcon className="h-4 w-4" />{message.fileName || "Download file"}</a>}{message.body && <p className="whitespace-pre-wrap text-sm leading-6">{message.body}</p>}<div className={`mt-1.5 flex items-center justify-end gap-1 text-[10px] ${mine ? "text-white/55" : "text-muted-foreground"}`}>{formatTime(message.createdAt)} {mine && (message.status === "read" ? <CheckCheck className="h-3 w-3 text-cyan-300" /> : <Check className="h-3 w-3" />)}</div></div></div>; })}</div><div className="border-t border-border bg-card px-3 py-3 sm:px-6"><div className="mx-auto flex max-w-4xl items-end gap-2 rounded-2xl border border-border bg-background p-2 shadow-sm"><label className="grid h-10 w-10 shrink-0 cursor-pointer place-items-center rounded-xl text-muted-foreground hover:bg-muted hover:text-primary"><Paperclip className="h-5 w-5" /><input type="file" className="hidden" accept="image/*,.pdf,.txt,.zip" onChange={event => { const file = event.target.files?.[0]; if (file) void sendFile(file); event.currentTarget.value = ""; }} /></label><textarea value={body} onChange={event => setBody(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); void submit(); } }} placeholder={recording ? "Recording a voice note…" : "Write a message…"} rows={1} className="max-h-28 min-h-10 flex-1 resize-none bg-transparent px-2 py-2.5 text-sm outline-none placeholder:text-muted-foreground/70" disabled={recording || busy} /><button className="grid h-10 w-10 shrink-0 place-items-center rounded-xl text-muted-foreground hover:bg-muted"><Smile className="h-5 w-5" /></button>{recording ? <button onClick={stopRecording} className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-rose-500 text-white shadow-lg shadow-rose-500/20"><span className="h-3 w-3 rounded-sm bg-white" /></button> : body.trim() ? <button onClick={() => void submit()} className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-lg shadow-primary/20"><Send className="h-4 w-4" /></button> : <button onClick={() => void startRecording()} className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-lg shadow-primary/20"><Mic className="h-4 w-4" /></button>}</div><p className="mx-auto mt-2 max-w-4xl px-2 text-[10px] font-semibold text-muted-foreground">Messages sync through the Icegram backend · {busy ? "Uploading…" : "Enter to send · Shift + Enter for a new line"}</p></div></section>;
}

function NewChatDialog({ onClose, onStart }: { onClose: () => void; onStart: (userId: number) => void }) {
  const [query, setQuery] = useState("");
  const searchInput = useMemo(() => ({ query }), [query]);
  const results = trpc.search.users.useQuery(searchInput, { enabled: query.trim().length > 1 });
  return <Modal title="Start a new conversation" onClose={onClose}><div className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="Search username or ICE-4827-1936" className="h-10 w-full rounded-xl border border-border bg-background pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-primary/20" /></div><div className="mt-4 max-h-72 space-y-1 overflow-y-auto">{query.length > 1 && results.isLoading && <p className="p-4 text-center text-xs text-muted-foreground">Searching…</p>}{query.length > 1 && !results.isLoading && (results.data ?? []).length === 0 && <p className="p-4 text-center text-xs text-muted-foreground">No users found. Try a username or full Icegram ID.</p>}{(results.data ?? []).map((user: any) => <button key={user.id} onClick={() => onStart(user.id)} className="flex w-full items-center gap-3 rounded-xl p-3 text-left hover:bg-muted"><Avatar name={user.displayName || user.name} image={user.avatarUrl} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{user.displayName || user.name || "Icegram user"}</p><p className="truncate text-xs text-muted-foreground">@{user.username || "no username"} · {user.icegramId || "identity pending"}</p></div><ArrowUpRight className="h-4 w-4 text-muted-foreground" /></button>)}</div></Modal>;
}

function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-[#071a33]/40 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-3xl border border-border bg-card p-5 shadow-2xl"><div className="flex items-center justify-between"><h2 className="text-lg font-black">{title}</h2><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button></div>{children}</div></div>; }

function StoriesPanel({ profile }: { profile: any }) {
  const [body, setBody] = useState("");
  const storiesQuery = trpc.stories.list.useQuery();
  const create = trpc.stories.create.useMutation({ onSuccess: () => { setBody(""); storiesQuery.refetch(); toast.success("Story posted for 24 hours"); } });
  return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-4xl"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-black uppercase tracking-[.2em] text-primary">Your circle</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">Stories</h1><p className="mt-2 text-sm text-muted-foreground">Share a moment. It disappears after 24 hours.</p></div><div className="rounded-2xl bg-primary/10 px-4 py-3 text-xs font-bold text-primary"><Globe2 className="mr-2 inline h-4 w-4" /> Visibility is controlled per story</div></div><div className="mt-8 rounded-3xl border border-border bg-card p-5 shadow-sm"><div className="flex gap-3"><Avatar name={profile?.displayName || profile?.name} image={profile?.avatarUrl} /><textarea value={body} onChange={event => setBody(event.target.value)} placeholder="Share what’s happening…" className="min-h-24 flex-1 resize-none rounded-2xl bg-muted/70 p-4 text-sm outline-none focus:ring-2 focus:ring-primary/20" /></div><div className="mt-4 flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">Text stories are live now · media stories use the same storage pipeline as chat.</span><button disabled={!body.trim() || create.isPending} onClick={() => create.mutate({ type: "text", body, visibility: "contacts" })} className="rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground disabled:opacity-50">{create.isPending ? "Posting…" : "Post story"}</button></div></div><div className="mt-8 grid gap-4 sm:grid-cols-2">{(storiesQuery.data ?? []).map(({ story, user }: any) => <article key={story.id} className="overflow-hidden rounded-3xl border border-border bg-card shadow-sm"><div className="flex items-center gap-3 p-4"><Avatar name={user.displayName || user.name} image={user.avatarUrl} size="sm" /><div><p className="text-sm font-bold">{user.displayName || user.name}</p><p className="text-[10px] text-muted-foreground">@{user.username || "icegram"} · {formatTime(story.createdAt)}</p></div></div><div className="min-h-40 bg-gradient-to-br from-[#153964] via-[#1b6b93] to-[#38c4cf] p-6 text-white"><p className="text-lg font-bold leading-7">{story.body}</p></div><div className="px-4 py-3 text-[10px] font-semibold text-muted-foreground">Expires {new Date(story.expiresAt).toLocaleString()}</div></article>)}{(storiesQuery.data ?? []).length === 0 && <div className="sm:col-span-2 rounded-3xl border border-dashed border-border p-10 text-center"><Star className="mx-auto h-8 w-8 text-muted-foreground/50" /><p className="mt-3 text-sm font-bold">Your story tray is empty</p><p className="mt-1 text-xs text-muted-foreground">Post the first update for your circle.</p></div>}</div></div></section>;
}

function ContactsPanel({ onOpenChat }: { onOpenChat: (userId: number) => void }) {
  const [query, setQuery] = useState("");
  const contactsQuery = trpc.contacts.list.useQuery();
  const searchInput = useMemo(() => ({ query }), [query]);
  const results = trpc.search.users.useQuery(searchInput, { enabled: query.length > 1 });
  const add = trpc.contacts.add.useMutation({ onSuccess: () => { contactsQuery.refetch(); toast.success("Contact saved"); } });
  return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-4xl"><p className="text-xs font-black uppercase tracking-[.2em] text-primary">People</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">Contacts</h1><p className="mt-2 text-sm text-muted-foreground">Find people by username or their private Icegram ID.</p><div className="relative mt-7 max-w-xl"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search people" className="h-10 w-full rounded-xl border border-border bg-card pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-primary/20" /></div>{query.length > 1 && <div className="mt-3 max-w-xl rounded-2xl border border-border bg-card p-2">{(results.data ?? []).map((user: any) => <div key={user.id} className="flex items-center gap-3 rounded-xl p-3 hover:bg-muted"><Avatar name={user.displayName || user.name} image={user.avatarUrl} size="sm" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{user.displayName || user.name}</p><p className="truncate text-xs text-muted-foreground">@{user.username || "no username"} · {user.icegramId}</p></div><button onClick={() => add.mutate({ userId: user.id })} className="rounded-lg bg-primary/10 px-3 py-2 text-xs font-bold text-primary">Add</button><button onClick={() => onOpenChat(user.id)} className="rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground">Chat</button></div>)}{!results.isLoading && (results.data ?? []).length === 0 && <p className="p-3 text-xs text-muted-foreground">No users found.</p>}</div>}<div className="mt-8 grid gap-3 sm:grid-cols-2">{(contactsQuery.data ?? []).map(({ user, contact }: any) => <div key={contact.id} className="flex items-center gap-3 rounded-2xl border border-border bg-card p-4"><Avatar name={user.displayName || user.name} image={user.avatarUrl} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{user.displayName || user.name}</p><p className="truncate text-xs text-muted-foreground">@{user.username || "no username"}</p></div><button onClick={() => onOpenChat(user.id)} className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 text-primary"><MessageCircle className="h-4 w-4" /></button></div>)}{(contactsQuery.data ?? []).length === 0 && <div className="sm:col-span-2 rounded-3xl border border-dashed border-border p-10 text-center"><UserRoundPlus className="mx-auto h-8 w-8 text-muted-foreground/50" /><p className="mt-3 text-sm font-bold">No contacts saved yet</p><p className="mt-1 text-xs text-muted-foreground">Search above to add someone.</p></div>}</div></div></section>;
}

function NotificationsPanel() { const query = trpc.notifications.list.useQuery(); const mark = trpc.notifications.markRead.useMutation({ onSuccess: () => query.refetch() }); return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-3xl"><div className="flex items-end justify-between"><div><p className="text-xs font-black uppercase tracking-[.2em] text-primary">Inbox</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">Notifications</h1></div><button onClick={() => mark.mutate({})} className="text-xs font-bold text-primary">Mark all read</button></div><div className="mt-8 space-y-2">{(query.data ?? []).map((item: any) => <div key={item.id} className={`flex gap-3 rounded-2xl border p-4 ${item.readAt ? "border-border bg-card" : "border-primary/20 bg-primary/5"}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary">{item.kind === "message" ? <MessageCircle className="h-4 w-4" /> : <Bell className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="text-sm font-bold">{item.title}</p><p className="mt-1 text-xs text-muted-foreground">{item.body}</p><p className="mt-2 text-[10px] font-semibold text-muted-foreground">{new Date(item.createdAt).toLocaleString()}</p></div>{!item.readAt && <button onClick={() => mark.mutate({ id: item.id })} className="self-start text-[10px] font-bold text-primary">Read</button>}</div>)}{(query.data ?? []).length === 0 && <div className="rounded-3xl border border-dashed border-border p-10 text-center"><Inbox className="mx-auto h-8 w-8 text-muted-foreground/50" /><p className="mt-3 text-sm font-bold">All caught up</p><p className="mt-1 text-xs text-muted-foreground">New chat notifications will appear here.</p></div>}</div></div></section>; }

function SettingsPanel({ profile, onProfileUpdate, onLogout }: { profile: any; onProfileUpdate: (value: any) => void; onLogout: () => void }) {
  const { theme, toggleTheme } = useTheme();
  const [displayName, setDisplayName] = useState(profile?.displayName || profile?.name || ""); const [username, setUsername] = useState(profile?.username || ""); const [bio, setBio] = useState(profile?.bio || ""); const [visibility, setVisibility] = useState(profile?.phoneVisibility || "nobody");
  const update = trpc.profile.update.useMutation({ onSuccess: data => { onProfileUpdate(data); toast.success("Profile updated"); }, onError: error => toast.error(error.message) });
  const sessions = trpc.sessions.list.useQuery(); const revoke = trpc.sessions.revoke.useMutation({ onSuccess: () => sessions.refetch() });
  return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-3xl"><p className="text-xs font-black uppercase tracking-[.2em] text-primary">Your account</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">Settings</h1><div className="mt-8 space-y-5"><div className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center gap-4"><Avatar name={displayName} image={profile?.avatarUrl} size="lg" /><div><p className="text-lg font-black">{displayName || "Your profile"}</p><p className="text-sm text-muted-foreground">{profile?.icegramId || "Generating your Icegram ID…"}</p></div></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Display name" value={displayName} onChange={setDisplayName} /><Field label="Username" prefix="@" value={username} onChange={setUsername} /><label className="sm:col-span-2"><span className="mb-2 block text-xs font-bold text-muted-foreground">Bio</span><textarea value={bio} onChange={event => setBio(event.target.value)} maxLength={240} className="min-h-20 w-full resize-none rounded-xl border border-border bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-primary/20" placeholder="A short introduction" /></label></div><button onClick={() => update.mutate({ displayName, username, bio, phoneVisibility: visibility as any })} disabled={update.isPending} className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground">{update.isPending ? "Saving…" : "Save profile"}</button></div><div className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-black">Privacy controls</p><p className="mt-1 text-xs text-muted-foreground">Your phone number is never part of the public identity by default.</p></div><ShieldCheck className="h-5 w-5 text-primary" /></div><div className="mt-5 flex flex-wrap gap-2">{["nobody", "contacts", "everyone"].map(option => <button key={option} onClick={() => setVisibility(option)} className={`rounded-xl border px-3 py-2 text-xs font-bold capitalize ${visibility === option ? "border-primary bg-primary/10 text-primary" : "border-border text-muted-foreground"}`}>{option}</button>)}</div><div className="mt-5 flex items-center justify-between border-t border-border pt-5"><div><p className="text-sm font-black">Theme</p><p className="mt-1 text-xs text-muted-foreground">Choose a comfortable reading mode.</p></div><button onClick={toggleTheme} className="flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-bold capitalize">{theme === "dark" ? <Moon className="h-4 w-4" /> : <Sun className="h-4 w-4" />}{theme}</button></div></div><div className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-black">Active sessions</p><p className="mt-1 text-xs text-muted-foreground">Review devices connected to your account.</p></div><Headphones className="h-5 w-5 text-muted-foreground" /></div><div className="mt-4 space-y-2">{(sessions.data ?? []).map((session: any) => <div key={session.id} className="flex items-center gap-3 rounded-xl bg-muted/60 p-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-card"><Globe2 className="h-4 w-4 text-primary" /></div><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{session.deviceName}</p><p className="truncate text-[10px] text-muted-foreground">Last active {new Date(session.lastSeenAt).toLocaleString()}</p></div><button onClick={() => revoke.mutate({ id: session.id })} className="text-[10px] font-bold text-destructive">Revoke</button></div>)}</div></div><div className="flex items-center justify-between rounded-3xl border border-rose-200 bg-rose-50 p-5 dark:border-rose-900/50 dark:bg-rose-950/20"><div><p className="text-sm font-black text-rose-700 dark:text-rose-300">Sign out of Icegram</p><p className="mt-1 text-xs text-rose-600/70 dark:text-rose-300/60">Your messages remain stored securely.</p></div><button onClick={onLogout} className="rounded-xl bg-rose-600 px-3 py-2 text-xs font-bold text-white">Sign out</button></div></div></div></section>;
}

function Field({ label, value, onChange, prefix }: { label: string; value: string; onChange: (value: string) => void; prefix?: string }) { return <label><span className="mb-2 block text-xs font-bold text-muted-foreground">{label}</span><div className="flex h-10 items-center rounded-xl border border-border bg-background px-3 focus-within:ring-2 focus-within:ring-primary/20">{prefix && <span className="text-sm text-muted-foreground">{prefix}</span>}<input value={value} onChange={event => onChange(event.target.value)} className="min-w-0 flex-1 bg-transparent text-sm outline-none" /></div></label>; }

function AdminPanel() { const query = trpc.admin.overview.useQuery(); return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-4xl"><p className="text-xs font-black uppercase tracking-[.2em] text-primary">Control room</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">Admin foundation</h1><p className="mt-2 text-sm text-muted-foreground">Role-protected operational signals for the Icegram team.</p><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Users", query.data?.users ?? 0, <Users />], ["Open reports", query.data?.openReports ?? 0, <Flag />], ["Conversations", query.data?.conversations ?? 0, <MessageCircle />], ["Messages", query.data?.messages ?? 0, <Send />]].map(([label, value, icon]) => <div key={String(label)} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between text-primary"><span className="text-xs font-bold text-muted-foreground">{label}</span>{icon}</div><p className="mt-4 text-3xl font-black">{String(value)}</p></div>)}</div><div className="mt-6 rounded-3xl border border-border bg-card p-5"><div className="flex items-center gap-3"><ShieldCheck className="h-5 w-5 text-emerald-500" /><div><p className="text-sm font-black">Secure by default</p><p className="mt-1 text-xs text-muted-foreground">Admin access is enforced server-side through the protected role field. Reports and moderation workflows are persisted for Phase 2 review tooling.</p></div></div></div></div></section>; }

function IceboxPanel() {
  const [query, setQuery] = useState("");
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const [kind, setKind] = useState<"note" | "link" | "task">("note");
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [url, setUrl] = useState("");
  const input = useMemo(() => ({ query: query.trim() || undefined, favoritesOnly }), [query, favoritesOnly]);
  const itemsQuery = trpc.icebox.list.useQuery(input);
  const create = trpc.icebox.create.useMutation({ onSuccess: () => { setTitle(""); setBody(""); setUrl(""); void itemsQuery.refetch(); toast.success("Saved to IceBox"); }, onError: error => toast.error(error.message) });
  const favorite = trpc.icebox.favorite.useMutation({ onSuccess: () => void itemsQuery.refetch() });
  const remove = trpc.icebox.remove.useMutation({ onSuccess: () => void itemsQuery.refetch() });
  return <section className="min-h-full flex-1 overflow-y-auto bg-background p-5 pb-24 sm:p-8 lg:pb-8"><div className="mx-auto max-w-5xl"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-black uppercase tracking-[.2em] text-primary">Private cloud locker</p><h1 className="mt-2 text-3xl font-black tracking-[-.04em]">IceBox</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">Keep ideas, links, tasks, and important files close—owned by your Icegram identity.</p></div><button onClick={() => setFavoritesOnly(value => !value)} className={`inline-flex items-center gap-2 rounded-xl border px-3 py-2 text-xs font-bold ${favoritesOnly ? "border-primary bg-primary/10 text-primary" : "border-border text-muted-foreground"}`}><Star className="h-4 w-4" /> Favorites only</button></div><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_1.25fr]"><div className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center gap-2 rounded-xl border border-border bg-background px-3"><Search className="h-4 w-4 text-muted-foreground" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search your IceBox" className="h-11 min-w-0 flex-1 bg-transparent text-sm outline-none" /></div><div className="mt-4 flex gap-2">{(["note", "link", "task"] as const).map(value => <button key={value} onClick={() => setKind(value)} className={`rounded-full px-3 py-1.5 text-xs font-bold capitalize ${kind === value ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`}>{value}</button>)}</div><div className="mt-4 space-y-3"><Field label="Title" value={title} onChange={setTitle} />{kind === "link" && <Field label="URL" value={url} onChange={setUrl} /> }<label><span className="mb-2 block text-xs font-bold text-muted-foreground">{kind === "task" ? "Task details" : "Notes"}</span><textarea value={body} onChange={event => setBody(event.target.value)} rows={4} className="w-full resize-none rounded-xl border border-border bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-primary/20" placeholder="Write something worth keeping…" /></label><button onClick={() => create.mutate({ kind, title, body: body || undefined, url: url || undefined, tags: [] })} disabled={create.isPending || !title.trim() || (kind === "link" && !url.trim())} className="w-full rounded-xl bg-primary py-3 text-xs font-bold text-primary-foreground disabled:opacity-50">{create.isPending ? "Saving…" : "Save to IceBox"}</button></div></div><div className="space-y-3">{itemsQuery.isLoading ? <div className="rounded-3xl border border-border bg-card p-8 text-center text-sm text-muted-foreground">Loading your locker…</div> : itemsQuery.data?.length ? itemsQuery.data.map(item => <article key={item.id} className="rounded-2xl border border-border bg-card p-4 shadow-sm"><div className="flex items-start gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary">{item.kind === "link" ? <ArrowUpRight className="h-4 w-4" /> : item.kind === "task" ? <Check className="h-4 w-4" /> : <Bookmark className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><h2 className="font-bold">{item.title}</h2><div className="flex gap-1"><button onClick={() => favorite.mutate({ id: item.id, favorite: !item.favorite })} className={item.favorite ? "text-amber-500" : "text-muted-foreground"}><Star className="h-4 w-4" fill={item.favorite ? "currentColor" : "none"} /></button><button onClick={() => remove.mutate({ id: item.id })} className="text-muted-foreground hover:text-destructive"><Trash2 className="h-4 w-4" /></button></div></div>{item.url && <a href={item.url} target="_blank" rel="noreferrer" className="mt-1 block truncate text-xs font-semibold text-primary">{item.url}</a>}{item.body && <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{item.body}</p>}<p className="mt-3 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/70">{item.kind} · {new Date(item.updatedAt).toLocaleDateString()}</p></div></div></article>) : <div className="rounded-3xl border border-dashed border-border bg-card p-10 text-center"><Bookmark className="mx-auto h-7 w-7 text-primary" /><p className="mt-4 font-bold">Your IceBox is empty</p><p className="mt-2 text-sm text-muted-foreground">Save a thought, link, or task from the composer.</p></div>}</div></div></div></section>;
}

function AppShell({ auth }: { auth: ReturnType<typeof useAuth> }) {
  const [view, setView] = useState<View>("chats"); const [activeChatId, setActiveChatId] = useState<number | null>(null); const [dialog, setDialog] = useState<"new" | "group" | "channel" | null>(null); const [installPrompt, setInstallPrompt] = useState<(() => void) | undefined>();
  const profileQuery = trpc.profile.me.useQuery(); const chatsQuery = trpc.chat.list.useQuery(undefined, { refetchInterval: 7000 }); const notificationsQuery = trpc.notifications.list.useQuery(undefined, { refetchInterval: 15000 });
  const startChat = trpc.chat.start.useMutation({ onSuccess: chat => { setActiveChatId(chat.id); setView("chats"); chatsQuery.refetch(); setDialog(null); } }); const createGroup = trpc.chat.createGroup.useMutation({ onSuccess: chat => { setActiveChatId(chat.id); setView("chats"); chatsQuery.refetch(); setDialog(null); toast.success("Group created"); } }); const createChannel = trpc.chat.createChannel.useMutation({ onSuccess: chat => { setActiveChatId(chat.id); setView("chats"); chatsQuery.refetch(); setDialog(null); toast.success("Channel created"); } });
  const chats = chatsQuery.data ?? []; const activeChat = chats.find(chat => chat.id === activeChatId) ?? null;
  useEffect(() => { if (!activeChatId && chats[0]) setActiveChatId(chats[0].id); }, [activeChatId, chats]);
  useEffect(() => { const listener = (event: Event) => { const prompt = event as Event & { prompt: () => Promise<void> }; event.preventDefault(); setInstallPrompt(() => () => { void prompt.prompt(); }); }; window.addEventListener("beforeinstallprompt", listener); return () => window.removeEventListener("beforeinstallprompt", listener); }, []);
  if (profileQuery.isLoading || !profileQuery.data) return <div className="grid min-h-screen place-items-center bg-background"><div className="text-center"><IcegramLogo className="justify-center" /><p className="mt-5 text-sm font-semibold text-muted-foreground">Preparing your private identity…</p></div></div>;
  const profile = profileQuery.data; const unread = (notificationsQuery.data ?? []).filter(item => !item.readAt).length;
  const openContactChat = async (userId: number) => { try { const chat = await startChat.mutateAsync({ userId }); setActiveChatId(chat.id); setView("chats"); await chatsQuery.refetch(); } catch (error: any) { toast.error(error?.message || "Could not open chat"); } };
  return <div className="flex min-h-screen flex-col bg-background text-foreground lg:flex-row"><Sidebar view={view} setView={setView} profile={profile} onLogout={auth.logout} notificationCount={unread} onInstall={installPrompt} /><main className="flex min-h-0 flex-1">{view === "chats" && <div className="flex min-h-0 w-full flex-col md:flex-row"><ChatList chats={chats} activeId={activeChatId} onSelect={setActiveChatId} onNew={() => setDialog("new")} onGroup={() => setDialog("group")} onChannel={() => setDialog("channel")} profile={profile} />{activeChat ? <ChatPane chat={activeChat} profile={profile} onBack={() => setActiveChatId(null)} /> : <div className="hidden flex-1 place-items-center bg-[#f7fbfe] dark:bg-background md:grid"><div className="text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-3xl bg-primary/10 text-primary"><MessageCircle className="h-8 w-8" /></div><p className="mt-5 text-lg font-black">Select a conversation</p><p className="mt-2 text-sm text-muted-foreground">Your Icegram inbox is ready.</p></div></div>}</div>}{view === "icebox" && <IceboxPanel />}{view === "stories" && <StoriesPanel profile={profile} />}{view === "contacts" && <ContactsPanel onOpenChat={openContactChat} />}{view === "notifications" && <NotificationsPanel />}{view === "settings" && <SettingsPanel profile={profile} onProfileUpdate={value => profileQuery.refetch().then(() => value)} onLogout={auth.logout} />}{view === "admin" && profile.role === "admin" && <AdminPanel />}</main><MobileNav view={view} setView={setView} count={unread} />{dialog === "new" && <NewChatDialog onClose={() => setDialog(null)} onStart={openContactChat} />}{dialog === "group" && <GroupDialog onClose={() => setDialog(null)} onCreate={(title, description) => createGroup.mutate({ title, description, memberIds: [] })} />}{dialog === "channel" && <ChannelDialog onClose={() => setDialog(null)} onCreate={(title, description) => createChannel.mutate({ title, description })} />}</div>;
}

function GroupDialog({ onClose, onCreate }: { onClose: () => void; onCreate: (title: string, description?: string) => void }) { const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); return <Modal title="Create a group" onClose={onClose}><p className="mt-2 text-xs text-muted-foreground">You can add members and tune permissions from the group workspace as it grows.</p><div className="mt-5 space-y-3"><Field label="Group name" value={title} onChange={setTitle} /><Field label="Description" value={description} onChange={setDescription} /></div><button onClick={() => onCreate(title, description)} disabled={title.trim().length < 2} className="mt-5 w-full rounded-xl bg-primary py-3 text-xs font-bold text-primary-foreground disabled:opacity-50">Create group</button></Modal>; }
function ChannelDialog({ onClose, onCreate }: { onClose: () => void; onCreate: (title: string, description?: string) => void }) { const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); return <Modal title="Create a channel" onClose={onClose}><p className="mt-2 text-xs text-muted-foreground">Start a channel for announcements, creator posts, or a focused public conversation.</p><div className="mt-5 space-y-3"><Field label="Channel name" value={title} onChange={setTitle} /><Field label="Description" value={description} onChange={setDescription} /></div><button onClick={() => onCreate(title, description)} disabled={title.trim().length < 2} className="mt-5 w-full rounded-xl bg-primary py-3 text-xs font-bold text-primary-foreground disabled:opacity-50">Create channel</button></Modal>; }

export default function Home() { const auth = useAuth(); if (auth.loading) return <div className="grid min-h-screen place-items-center bg-background"><IcegramLogo /><div className="absolute mt-28 text-xs font-semibold text-muted-foreground">Checking your Icegram session…</div></div>; if (!auth.isAuthenticated) return <Landing onLogin={startLogin} />; return <AppShell auth={auth} />; }
